def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Find contiguous bands of rows containing non-background pattern cells.
    active = [r for r, row in enumerate(grid) if any(v != bg for v in row)]
    bands = []
    for r in active:
        if not bands or r != bands[-1][-1] + 1:
            bands.append([r])
        else:
            bands[-1].append(r)

    if not bands:
        return out

    # Extend the right edge of the first patterned band where the later
    # repeated band shows foreground continuing beyond it.
    first = bands[0]
    other = bands[-1] if len(bands) > 1 else None
    for k, r in enumerate(first):
        end = max((c for c, v in enumerate(grid[r]) if v != bg), default=-1)
        if end < 0:
            continue
        # Use the matching row of the repeated motif, if present.
        if other and k < len(other):
            rr = other[k]
            for c in range(end + 1, w):
                if grid[rr][c] != bg:
                    out[r][c] = 1
        else:
            # A consistent blank right margin is the part to highlight.
            for c in range(end + 1, w):
                out[r][c] = 1
    return out
